import { useEffect, useState } from 'react'
import { CreditCard, RefreshCw, UserRoundPlus } from 'lucide-react'
import { getAdminResidents } from '../../api/admin'
import { getLastSeenUid, registerNfc } from '../../api/nfc'

export default function AdminDashboard() {
  const [residents, setResidents] = useState([]); const [uid, setUid] = useState(''); const [residentId, setResidentId] = useState(''); const [message, setMessage] = useState('')
  const load = () => { getAdminResidents().then(setResidents).catch(() => setMessage('Could not load residents.')); getLastSeenUid().then((data)=>data.nfc_uid && setUid(data.nfc_uid)).catch(()=>{}) }
  useEffect(() => { load(); const poll = setInterval(() => getLastSeenUid().then((data)=>data.nfc_uid && setUid(data.nfc_uid)).catch(()=>{}), 3000); return () => clearInterval(poll) }, [])
  const submit = async (event) => { event.preventDefault(); try { const result = await registerNfc(uid, Number(residentId)); setMessage(`Card linked to ${result.name}.`); setUid(''); setResidentId('') } catch (error) { setMessage(error.response?.data?.detail || 'Card registration failed.') } }
  return <div className="space-y-7"><div><p className="text-sm text-moss">System administration</p><h1 className="text-4xl text-forest">NFC card registry</h1></div><section className="grid gap-6 lg:grid-cols-[1fr_.9fr]"><form onSubmit={submit} className="panel p-6"><div className="flex items-center gap-2"><CreditCard className="text-terracotta"/><h2 className="section-title">Link a resident card</h2></div><p className="mt-2 text-sm text-moss">Ask the resident to tap their card at the station. The most recently seen UID is polled from the backend.</p><label className="mt-6 block text-sm font-semibold">Last-seen card UID<input value={uid} onChange={(e)=>setUid(e.target.value.toUpperCase())} required className="mt-2 w-full border border-line bg-cream p-3 font-mono outline-none focus:border-forest"/></label><button type="button" onClick={load} className="mt-2 flex items-center gap-2 text-sm font-semibold text-moss hover:text-forest"><RefreshCw size={15}/> Refresh last-seen UID</button><label className="mt-5 block text-sm font-semibold">Resident<select value={residentId} onChange={(e)=>setResidentId(e.target.value)} required className="mt-2 w-full border border-line bg-cream p-3"><option value="">Select a resident</option>{residents.filter((item)=>item.id !== 0).map((item)=><option key={item.id} value={item.id}>{item.name} · #{item.id}</option>)}</select></label><button className="mt-6 flex items-center gap-2 bg-terracotta px-4 py-3 font-bold text-paper hover:bg-clay"><UserRoundPlus size={17}/> Register card</button>{message && <p className="mt-4 border-l-4 border-terracotta bg-[#fff2df] p-3 text-sm text-clay">{message}</p>}</form><aside className="bg-forest p-7 text-paper"><h2 className="font-display text-3xl">Station workflow</h2><ol className="mt-6 space-y-5 text-sm leading-6 text-[#dce5da]"><li><b className="text-terracotta">01</b> Connect PN532 serial bridge to the laptop.</li><li><b className="text-terracotta">02</b> Have the resident tap their unregistered card.</li><li><b className="text-terracotta">03</b> Select their profile and link the last-seen UID.</li><li><b className="text-terracotta">04</b> The next scan resolves the profile and enables rewards.</li></ol></aside></section></div>
}
